public class SafeCalcTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String call(String a, String b) {
        try {
            return SafeCalc.divide(a, b);
        } catch (Exception e) {
            return "threw " + e.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("divide(\"10\", \"2\")", "5", call("10", "2"));
        check("divide(\"7\", \"2\") truncates", "3", call("7", "2"));
        check("divide(\"-9\", \"3\")", "-3", call("-9", "3"));
        check("divide(\"0\", \"5\")", "0", call("0", "5"));
        check("divide(\"ten\", \"2\")", "not a number", call("ten", "2"));
        check("divide(\"4\", \"x\")", "not a number", call("4", "x"));
        check("divide(\"10\", \"0\")", "division by zero", call("10", "0"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

